 w.append(el('h3',{},'Land intelligence'),el('p',{class:'sub'},p.formattedAddress||p.address||address),el('p',{class:'hint'},a.landTypeVerified?'Property type supported by resolved evidence.':'Land was selected for research; property type still needs confirmation.'));
