 const factLabels={lotSizeSqFt:'Lot size (square feet)',parcelNumber:'Parcel / APN',zoning:'Zoning',roadAccess:'Road access',utilities:'Utilities',floodZone:'Flood zone',annualTaxes:'Annual taxes',assessedValue:'Assessed value',lastSalePrice:'Prior sale price',lastSaleDate:'Prior sale date',currentListPrice:'Current list price'};
 const facts=el('div',{class:'land-research-facts'},el('h4',{},'Property research results'));
 for(const [key,label]of Object.entries(factLabels)){const f=report.facts[key]||{},moneyField=['annualTaxes','assessedValue','lastSalePrice','currentListPrice'].includes(key),card=el('details',{class:'land-fact'});card.append(el('summary',{},label+': '+(f.status==='conflicting'?'Conflicting sources':fmt(f.value,moneyField?'money':'text'))+' · '+(f.status||'missing')));for(const row of f.sources||[])card.append(el('p',{},String(row.value??'Unknown')+' · '+(row.source||'Source')),/^https?:\/\//.test(row.sourceUrl||'')?el('a',{href:row.sourceUrl,target:'_blank',rel:'noopener noreferrer'},'Open supporting source'):null);if(!f.sources?.length)card.append(el('p',{class:'hint'},'No accepted source supplied this field.'));facts.append(card);}w.append(facts);
 w.append(el('h4',{},'Researched closed land sales'),el('p',{class:'hint'},'Recent sales with known parcel sizes and supported distances. Unit prices are descriptive until zoning, access and utilities are comparable.'));
