function availableHelp(){const aff=hasRole(state.user,'affiliate'),admin=!!state.access?.adminUnlimited;return PLATFORM_HELP.filter(x=>!aff||['affiliate','upgrade','settings','feedback','support'].includes(x[3])).concat(admin?[['Admin charts and month comparisons','admin chart monthly compare growth dates time analytics','Admin growth charts support line, bar and area styles, month comparisons and dates with optional minute-level times.','admin']]:[]);}
function helpMatches(q){const words=q.toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(x=>x.length>2&&!['how','the','can','want','with','that','this','have','where','does','what','please'].includes(x));return availableHelp().map(x=>({x,score:words.reduce((n,w)=>n+((x[0]+' '+x[1]+' '+x[2]).toLowerCase().includes(w)?1:0),0)})).filter(x=>!words.length||x.score).sort((a,b)=>b.score-a.score).map(x=>x.x).slice(0,6);}
function platformHelpPanel(includeActions=true){const w=el('section',{class:'platform-help'}),input=el('input',{placeholder:'Ask how to edit, delete, find buyers, use charts…','aria-label':'Search platform navigation help'}),results=el('div',{class:'guide-search-results'});const draw=()=>{results.replaceChildren();for(const x of helpMatches(input.value))results.append(el('button',{class:'help-result',onclick:()=>navigateFromGuide(x[3])},[el('b',{},x[0]),el('span',{},x[2]),el('small',{},'Open this tool')]));if(!results.children.length)results.append(el('p',{},'I do not have a verified answer for that yet. Contact support or report the issue below.'));};input.oninput=draw;w.append(el('h3',{},'Find your way around Better'),input,results);if(includeActions)w.append(guideSupportFooter());draw();return w;}
