 node('text',{x:55,y:248,fill:'var(--ink-soft)','font-size':12},data.comparison?'Day 1':series[0].buckets[0]?.label||'');node('text',{x:680,y:248,fill:'var(--ink-soft)','font-size':12,'text-anchor':'end'},data.comparison?'Day '+count:series[0].buckets.at(-1)?.label||'');w.append(svg);
