function organizeAdminSections(wrap){
 const nodes=[...wrap.children],groups=[],key='better-admin-sections:'+state.user.id;let saved={};try{const stored=JSON.parse(localStorage.getItem(key)||'{}');if(stored&&typeof stored==='object'&&!Array.isArray(stored))saved=stored;}catch{}
 const labels={'Acquisition campaigns':['Acquisition campaigns','Partner accounts, campaign results and external-payment records'],'Manage title companies':['Manage title companies','Open title-company directory management'],'Revenue':['Revenue','Memberships, promotions and other revenue totals'],'User activity':['Activity and growth','Activity totals, charts and month comparisons'],'Demo accounts':['Demo accounts and previews','Create controlled test accounts and preview experiences'],'User inspector':['Members — User Inspector','Search members and manage account access'],'Verify closed deals':['Deal verification','Review pending closed-deal confirmations'],'Seller verification requests':['Identity verification','Review requests and manage verification badges'],'Account verification':['Account verification','Search and manage account verification']};
 let current=null;const header=[];
 for(const node of nodes){const title=node.classList.contains('sectiontitle')?node.textContent.trim():null;if(title&&labels[title]){const [name,description]=labels[title];const details=el('details',{class:'card admin-section'}),body=el('div',{class:'admin-section-body'});details.append(el('summary',{},[el('span',{class:'admin-section-title'},name),el('small',{},description)]),body);details.open=saved[title]===true;details.ontoggle=()=>{saved[title]=details.open;try{localStorage.setItem(key,JSON.stringify(saved));}catch{}};groups.push(details);current=body;}else if(current)current.appendChild(node);else header.push(node);}
 const actions=el('div',{class:'admin-section-controls'},[serviceAction('Expand all',async()=>{groups.forEach(g=>g.open=true);}),serviceAction('Collapse all',async()=>{groups.forEach(g=>g.open=false);})]);wrap.replaceChildren(...header,actions,...groups);return wrap;
}

async function inspectorProfilePanel(member,onSave){
 const {profile:p}=await api('GET','/api/admin/users/'+encodeURIComponent(member.id)+'/profile'),w=el('section',{class:'inspector-profile service-form'});
 if(p.avatarUrl)w.append(el('img',{class:'inspector-avatar',src:p.avatarUrl,alt:p.name+' profile photo'}));
 const contact=el('details',{class:'inspector-contact-menu'}),choices=el('div',{class:'inspector-contact-options'});contact.append(el('summary',{'aria-label':'Contact '+p.name,title:'Send a message or email'},iconSvg('mail',18)),choices);
 const message=serviceAction('In-platform message',async()=>go('chat',{chatUserId:member.id}));message.disabled=member.id===state.user.id;choices.append(message);
 const email=serviceAction('Email',async()=>go('emailcenter',{emailRecipient:{id:member.id,name:p.name,email:p.email,eligible:p.emailContactEligible}}));email.disabled=!p.email||!p.emailContactEligible;choices.append(email);if(!p.emailContactEligible)choices.append(el('p',{class:'hint'},!p.emailVerified?'Confirm the email first. Use the reminder below.':'Email Center requires product-email opt-in. In-platform messaging remains available.'));w.append(contact);
 if(!p.emailVerified){const reminder=serviceAction('Remind to confirm email',async()=>{if(!confirm('Send a confirmation email to '+p.email+'?'))return;await api('POST','/api/admin/users/'+encodeURIComponent(member.id)+'/remind-verification',{});toast('Confirmation email sent','ok');});reminder.disabled=!!member.demo;w.append(reminder);}
 const account=el('dl',{class:'inspector-account'});for(const [label,value]of [['Account ID',p.id],['Email',p.email],['Email confirmed',p.emailVerified?'Yes':'No'],['Member since',p.createdAt?new Date(p.createdAt).toLocaleString():'Unavailable'],['Last active',p.lastActiveAt?new Date(p.lastActiveAt).toLocaleString():'No recorded activity'],['Roles',(p.roles||[]).join(', ')],['Company',p.companyId||'None']])account.append(el('dt',{},label),el('dd',{},value));w.append(account);
 if(p.affiliateApplication){const a=p.affiliateApplication;w.append(el('h4',{},'Affiliate application'),el('p',{},a.status==='not_submitted'?'Not submitted — choosing an affiliate account does not submit an application. The member must open Affiliate Center and Apply.':'Status: '+a.status+(a.createdAt?' · Submitted '+new Date(a.createdAt).toLocaleString():'')),el('p',{class:'hint'},a.termsAcceptedAt?'Affiliate terms accepted '+new Date(a.termsAcceptedAt).toLocaleString():'Affiliate terms have not been accepted.'));}
 if(p.serviceProfile?.enabled){const sp=p.serviceProfile;w.append(el('h4',{},'Service business'),el('p',{},[sp.businessName,sp.categories.join(' · '),sp.areas.join(' · '),sp.description,sp.availability,sp.pricing].filter(Boolean).join(' — ')));}
 if(p.buyBox)w.append(el('h4',{},'Buying criteria'),el('p',{},[p.buyBox.states.join(', '),p.buyBox.propertyTypes.join(', '),p.buyBox.minPrice!==null?'Minimum '+money(p.buyBox.minPrice):null,p.buyBox.maxPrice!==null?'Maximum '+money(p.buyBox.maxPrice):null].filter(Boolean).join(' · ')));
 if(member.role!=='admin'){const access=el('details',{class:'inspector-edit'}),accessBody=el('div');access.append(el('summary',{},'Membership grants and access'),accessBody);openAdminAccessModal(member,onSave,accessBody);w.append(access);}
 if(p.membershipHistory?.length){const history=el('details',{},el('summary',{},'Membership grant history'));for(const g of p.membershipHistory)history.append(el('p',{class:'hint'},[g.plan,g.createdAt?new Date(g.createdAt).toLocaleString():null,g.until?'Until '+new Date(g.until).toLocaleDateString():null,g.reason,g.revokedAt?'Revoked':null].filter(Boolean).join(' · ')));w.append(history);}
 const edit=el('details',{class:'inspector-edit'}),form=el('div',{class:'service-form'});edit.append(el('summary',{},'Edit basic profile'),form);const fields={};for(const [key,label,max,type]of [['name','Name',100,'text'],['username','Username',30,'text'],['phone','Phone',40,'tel'],['bio','Bio',400,'textarea'],['location','Location',80,'text'],['investmentMarkets','Investment markets (state abbreviations)',60,'text']]){fields[key]=serviceField(form,label,key==='investmentMarkets'?(p[key]||[]).join(', '):p[key]||'',type);fields[key].maxLength=max;}
 form.append(serviceAction('Save profile changes',async()=>{const body=Object.fromEntries(Object.entries(fields).map(([k,v])=>[k,k==='investmentMarkets'?v.value.split(',').map(x=>x.trim()).filter(Boolean):v.value]));await api('PATCH','/api/admin/users/'+encodeURIComponent(member.id)+'/profile',{...body,expectedProfileVersion:p.profileVersion});toast('Member profile updated','ok');await onSave();},true));w.append(edit,serviceAction('View public profile',async()=>go('profile',{profileId:member.id})));
 if(p.profileChanges?.length){const audit=el('details',{},el('summary',{},'Recent admin profile changes'));for(const x of p.profileChanges)audit.append(el('p',{class:'hint'},new Date(x.at).toLocaleString()+' · '+x.fields.join(', ')));w.append(audit);}return w;
}

function broadcastHistoryCard(b){
 const w=el('details',{class:'broadcast-history-card'}),content=el('div',{class:'broadcast-history-content'});w.append(el('summary',{},[el('b',{},b.subject),el('span',{class:'hint'},[b.status,b.sentCount+' sent',b.failedCount+' failed',b.scheduledAt?new Date(b.scheduledAt).toLocaleString():null].filter(Boolean).join(' · '))]),content);let loaded=false,inFlight=false;
 const load=async()=>{if(inFlight)return;inFlight=true;content.replaceChildren(el('p',{class:'hint'},'Loading email contents…'));try{const {broadcast:d}=await api('GET','/api/admin/email-center/broadcasts/'+encodeURIComponent(b.id));content.replaceChildren(el('p',{class:'hint'},'From: '+(d.sender==='partners'?'partners@betterrealestate.org':'notifications@betterrealestate.org')),el('h4',{},d.headline||d.subject));if(d.body===null||d.body===undefined)content.append(el('p',{class:'hint'},'Email body was not retained for this older broadcast.'));else content.append(el('p',{class:'broadcast-body'},d.body));if(d.ctaLabel)content.append(el('p',{},'Button: '+d.ctaLabel));if(d.ctaUrl)content.append(el('p',{class:'hint'},d.ctaUrl));loaded=true;}catch(e){content.replaceChildren(el('p',{class:'errmsg'},e.message),serviceAction('Retry email contents',load));}finally{inFlight=false;}};w.ontoggle=()=>{if(w.open&&!loaded)load();};return w;
}
